(function(){'use strict';
const api=()=>window.CAGE_BACKEND,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let epoch=0,url=null;
const dialog=document.createElement('dialog');dialog.className='app-dialog ops-dialog';dialog.id='payment-receipt-dialog';document.body.append(dialog);
function close(){dialog.close();if(url)URL.revokeObjectURL(url);url=null;dialog.innerHTML='';}
window.addEventListener('cage:access-closed',()=>{epoch++;close();});
window.addEventListener('cage:session-ready',()=>{epoch++;close();});
function shell(title){dialog.innerHTML=`<div class="dialog-heading"><h2>${esc(title)}</h2><button type="button" data-receipt-close>Close</button></div><div data-receipt-body></div><p role="alert" data-receipt-error></p>`;dialog.querySelector('[data-receipt-close]').onclick=close;if(!dialog.open)dialog.showModal();return dialog.querySelector('[data-receipt-body]');}
async function open(id){const token=++epoch;const body=shell('Payment receipt');body.textContent='Loading receipt…';try{
 const r=await api().opsRpc('get_payment_receipt',{payment_key:id});if(token!==epoch||!dialog.open)return;
 const response=await fetch('./cage-logo-new.png');if(!response.ok)throw new Error('The CAGE logo could not load. Please retry.');
 const bytes=await CagePDF.createDocumentPDF(PDFLib,r,'receipt',await response.arrayBuffer(),new Date(r.createdAt));if(token!==epoch||!dialog.open)return;
 if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));
 body.innerHTML=`<p><strong>${esc(r.number)}</strong> · Invoice ${esc(r.invoiceNumber)}</p><a class="primary-button" download="${esc(r.number)}.pdf" href="${url}">Download receipt PDF</a><iframe title="Payment receipt preview" style="width:100%;height:48vh;border:1px solid #dce8ee;margin-top:16px" src="${url}"></iframe><form data-receipt-send><label class="field">Client email<input name="recipient" type="email" required maxlength="254" value="${esc(r.recipient||'')}"></label><button class="primary-button">Email receipt</button><p role="status" data-receipt-status></p></form><p>The receipt records this payment. Email is sent only when you choose Email receipt.</p>`;
 body.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button'),input=f.elements.recipient,status=f.querySelector('[data-receipt-status]');b.disabled=true;input.disabled=true;status.textContent='Sending receipt…';dialog.querySelector('[data-receipt-error]').textContent='';try{await api().sendPaymentReceipt(id,input.value.trim());if(token!==epoch)return;status.textContent='Receipt accepted by the email provider.';b.textContent='Receipt sent';}catch(err){if(token!==epoch)return;status.textContent='';dialog.querySelector('[data-receipt-error]').textContent=err.message;b.disabled=false;b.textContent='Retry email';}finally{if(token===epoch)input.disabled=false;}};
}catch(err){if(token===epoch){body.textContent='';dialog.querySelector('[data-receipt-error]').textContent=err.message;}}}
async function list(){const token=++epoch,body=shell('Payment receipts');body.textContent='Loading payments…';try{const rows=await api().managedRecords('invoice_payments');if(token!==epoch||!dialog.open)return;rows.sort((a,b)=>String(b.paid_on).localeCompare(String(a.paid_on)));body.innerHTML='<label class="field">Search receipts<input type="search" placeholder="Invoice, client or payment reference"></label><div data-receipt-list></div><div class="ops-actions"><button data-prev>Previous</button><span data-page></span><button data-next>Next</button></div>';let page=0;
const draw=()=>{const term=body.querySelector('input').value.toLowerCase(),matches=rows.filter(r=>[r.receipt_number,r.receipt_snapshot?.invoiceNumber,r.receipt_snapshot?.client,r.invoice_id,r.reference].join(' ').toLowerCase().includes(term));const pages=Math.max(1,Math.ceil(matches.length/20));page=Math.min(page,pages-1);body.querySelector('[data-receipt-list]').innerHTML=matches.slice(page*20,page*20+20).map(r=>`<div style="padding:12px;border-bottom:1px solid #dce8ee"><button type="button" data-payment="${esc(r.id)}">${esc(r.receipt_number||'Issue receipt')} · ${esc(r.receipt_snapshot?.invoiceNumber||r.invoice_id)}</button><p>${esc(r.receipt_snapshot?.client||'')} · ${esc(r.paid_on)} · ${esc(r.currency)} ${esc(Number(r.amount).toLocaleString())} · ${esc(r.reference)}</p></div>`).join('')||'<p>No recorded payments found. Use Record payment / deposit after receiving payment.</p>';body.querySelector('[data-page]').textContent=`${page+1} / ${pages}`;body.querySelector('[data-prev]').disabled=page===0;body.querySelector('[data-next]').disabled=page===pages-1;body.querySelectorAll('[data-payment]').forEach(b=>b.onclick=()=>open(b.dataset.payment));};body.querySelector('input').oninput=()=>{page=0;draw();};body.querySelector('[data-prev]').onclick=()=>{page--;draw();};body.querySelector('[data-next]').onclick=()=>{page++;draw();};draw();
}catch(err){if(token===epoch){body.textContent='';dialog.querySelector('[data-receipt-error]').textContent=err.message;}}}
const panel=document.querySelector('[data-view-panel="finance"] .ops-actions');if(panel){const button=document.createElement('button');button.textContent='Payment receipts';button.id='open-payment-receipts';button.onclick=list;panel.append(button);}window.CAGE_RECEIPTS={open,list};
})();
